/**
 * Map from user-friendly type names (used in the SDK's onDemand input
 * schema) to the platform's WorkflowFieldType value.
 *
 * `attachmentId` is the odd one out: `elementum_on_demand_trigger`'s own
 * `parameters[].type` terraform attribute (on_demand_trigger_resource.go)
 * only validates a bare "attachment" - there is no "attachment_id" spelling
 * at that layer, unlike every other row here where the wire string is just
 * the WorkflowFieldType name lowercased. automation/to-tf.ts special-cases
 * ATTACHMENT_ID -> "attachment" (and from-tf.ts the inverse) rather than
 * renaming this alias, to avoid a breaking change to authored `onDemand({})`
 * calls that already use `type: "attachmentId"`.
 */
export const FIELD_TYPE_MAP = {
    text: "TEXT",
    number: "NUMBER",
    decimal: "DECIMAL",
    boolean: "BOOLEAN",
    date: "DATE",
    datetime: "DATETIME",
    user: "USER",
    json: "JSON",
    object: "OBJECT",
    attachmentId: "ATTACHMENT_ID",
    record: "ASPECT_RECORD",
};
/** On-demand `type: "record"` and its WorkflowFieldType / HCL spellings. */
export function isOnDemandRecordType(type) {
    return type === "record" || type === "ASPECT_RECORD";
}
/**
 * Maps a user-friendly FieldTypeAlias to the TypeScript type it represents.
 * Used to derive the phantom T in Ref<T> for trigger inputs.
 */
/**
 * Maps GraphQL __typename values for aspect fields to WorkflowFieldType.
 * Used when generating app definitions from Hydra's field metadata.
 */
export const ASPECT_FIELD_TYPE_NAME_TO_WORKFLOW_FIELD_TYPE = {
    AspectTextField: "TEXT",
    AspectHandleField: "HANDLE",
    AspectHtmlField: "RICH_TEXT",
    AspectNumberField: "NUMBER",
    AspectDecimalField: "DECIMAL",
    AspectBooleanField: "BOOLEAN",
    AspectDateField: "DATE",
    AspectDateTimeField: "DATETIME",
    AspectUserField: "USER_ID",
    AspectGroupField: "GROUP_ID",
    AspectAttachmentField: "ATTACHMENT_ID",
    AspectJsonField: "TEXT",
    AspectPicklistField: "PICKLIST",
    AspectMultiPicklistField: "MULTI_PICKLIST",
};
